const whatsappNumber = '';
const symptoms=['Feridas que demoram para cicatrizar','Feridas abertas por semanas ou meses','Feridas que não apresentam boa evolução','Dificuldades no processo de cicatrização','Feridas que exigem cuidados especializados','Cicatrizes que causam incômodo estético'];
document.querySelector('#symptoms').innerHTML=symptoms.map(t=>`<div class="symptom"><span class="icon">✧</span>${t}</div>`).join('');
const treatments=[['Feridas de difícil cicatrização','Feridas que apresentam dificuldade para evoluir e necessitam de acompanhamento especializado.'],['Feridas crônicas','Casos que permanecem por períodos prolongados e exigem avaliação cuidadosa e uma estratégia individualizada.'],['Dificuldades na cicatrização','Situações em que diferentes fatores podem interferir na recuperação da pele e dos tecidos.'],['Feridas pós-operatórias','Cuidados especializados para acompanhar o processo de cicatrização após procedimentos.'],['Cicatrizes','Acompanhamento voltado à recuperação e também à estética da cicatriz.']];
document.querySelector('#treatments').innerHTML=treatments.map(([t,p])=>`<article class="card"><span class="icon">✳</span><h3>${t}</h3><p>${p}</p></article>`).join('');
const resources=[['Laserterapia','Recurso terapêutico utilizado conforme a avaliação profissional e as necessidades específicas do processo de cuidado e cicatrização.'],['Ozonioterapia','Abordagem utilizada dentro de uma estratégia individualizada, conforme indicação e avaliação de cada caso.'],['Matriz de fibrina','Recurso aplicado em situações específicas como parte da abordagem voltada ao processo de reparação tecidual.'],['Camuflagem paramédica','Técnica voltada à estética da cicatriz, buscando melhorar sua aparência e proporcionar maior harmonia visual à pele.'],['Curativos especializados','Seleção da abordagem e dos cuidados adequados às características e necessidades de cada ferida.']];
document.querySelector('#resources').innerHTML=resources.map(([t,p],i)=>`<article class="resource"><b>0${i+1}</b><h3>${t}</h3><p>${p}</p></article>`).join('');
const steps=[['Avaliação','O primeiro passo é compreender o caso. A ferida ou cicatriz é avaliada cuidadosamente, considerando as necessidades individuais do paciente.'],['Definição da conduta','É definida a estratégia de cuidado mais adequada. Quando necessário, são considerados recursos e tecnologias para a abordagem.'],['Tratamento','O paciente inicia o tratamento de acordo com a conduta definida para suas necessidades.'],['Acompanhamento','A evolução é acompanhada ao longo do processo, permitindo ajustar os cuidados conforme a necessidade.']];
document.querySelector('#steps').innerHTML=steps.map(([t,p],i)=>`<article><div class="step-number">0${i+1}</div><h3>${t}</h3><p>${p}</p></article>`).join('');
const faq=[['Quando devo procurar uma profissional especializada em tratamento de feridas?','Quando uma ferida apresenta dificuldade para evoluir, demora mais do que o esperado para cicatrizar ou necessita de cuidados específicos, uma avaliação especializada pode ajudar a compreender melhor as necessidades do caso.'],['Toda ferida recebe o mesmo tipo de tratamento?','Não. Cada ferida possui características próprias. A conduta e os recursos utilizados dependem da avaliação profissional e das necessidades individuais de cada paciente.'],['Quais tratamentos e recursos podem ser utilizados?','A Dra. Luz Marina trabalha com recursos como laserterapia, ozonioterapia, matriz de fibrina, curativos especializados e camuflagem paramédica, sempre de acordo com a avaliação e indicação para cada caso.'],['A Dra. Luz Marina também atende casos relacionados a cicatrizes?','Sim. Além da atuação em cicatrização de feridas, possui ênfase em estética da cicatriz, incluindo técnicas como a camuflagem paramédica.'],['Quanto tempo uma ferida leva para cicatrizar?','O tempo varia de acordo com as características da ferida, as condições individuais do paciente e sua evolução durante o acompanhamento. Por isso, cada caso precisa ser avaliado individualmente.'],['Onde é realizado o atendimento?','O atendimento é realizado em Brasília – DF. Para informações sobre localização, disponibilidade e agendamento, entre em contato pelo WhatsApp.']];
document.querySelector('#faq').innerHTML=faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('');
const dialog=document.querySelector('#contact-dialog');document.querySelector('.whatsapp').addEventListener('click',()=>{if(whatsappNumber){window.open(`https://wa.me/${whatsappNumber}?text=${encodeURIComponent('Olá! Gostaria de agendar uma avaliação com a Dra. Luz Marina.')}`,'_blank','noopener,noreferrer')}else{dialog.showModal()}});document.querySelectorAll('.close,.close-contact').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
